        vm.assume(caller != address(0));
        vm.assume(depositAmount <= address(c).balance + 1e18); // avoid overflow in sum

        // Deposit from caller
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: depositAmount}("");
        vm.assume(success);

        // Record total before withdraw
