        // Actually, we can't iterate, so we use the invariant: totalBefore = address(c).balance + c.balances(caller)
        uint256 before = address(c).balance + c.balances(caller);

        // Withdraw
        vm.prank(caller);
        c.withdraw();

        // Check total after
