pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 deposit) public {
        vm.assume(caller != address(0));
        deposit = bound(deposit, 1, 1e18);

        // Record initial sum of all balances (only caller's balance exists initially)
        uint256 sumBefore = c.balances(caller);

        // Deposit
        vm.deal(caller, deposit);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: deposit}("");
        require(success);

        // Record sum after deposit
        uint256 sumAfterDeposit = sumBefore + deposit;

        // Withdraw
        vm.prank(caller);
        c.withdraw();

        // Check that sum of all balances hasn't changed from after deposit
        uint256 sumAfterWithdraw = c.balances(caller);

        // The invariant: the sum of balances should be non-decreasing after a withdraw
        // In the correct version, the balance goes to zero, so sum stays same
        // In the buggy version, the balance stays positive (deposit value), so sum increases
        assertTrue(sumAfterWithdraw <= sumAfterDeposit);
    }
}

