pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 depositAmount, uint256 withdrawAmount) public {
        vm.assume(sender != address(0));
        vm.assume(depositAmount > 0);
        vm.assume(withdrawAmount <= depositAmount);

        // Deposit
        vm.deal(sender, depositAmount);
        vm.prank(sender);
        (bool success, ) = address(c).call{value: depositAmount}("");
        require(success);

        // Get initial balances
        uint256 initialSenderBalance = c.balances(sender);
        uint256 initialContractBalance = address(c).balance;

        // Prank as sender and call withdraw
        vm.prank(sender);
        c.withdraw();

        // Check: after withdraw, sender's balance in contract must be 0
        assertTrue(c.balances(sender) == 0);
        // Check: contract's ether balance must have decreased by exactly the sender's previous balance (since no ether was sent to sender, balance just stayed same minus sent ether? Wait, in correct version balance decreases by the withdrawn amount; in mutant, no ether sent so contract balance stays same but sender's balance is zeroed. The rule: after withdraw, the change in contract balance equals the amount sent to caller. In mutant, change is 0 but sender's balance was reset, so the sum of all balances should equal contract balance. Actually, the simple rule: after withdraw, the sender's balance in contract is zero (already tried). So we need a different invariant.)
        // Alternative: after withdraw, the contract's total balance equals the sum of all balances of other users (since sender's balance is zeroed). We cannot easily sum all user balances without a list. So we use: after withdraw, the maximum of c.balances(sender) is 0? That is trivial.
        // The bug changes the value sent from balances[sender] to 0, so the contract's ether balance after withdraw is unchanged (no ether sent out). So the general rule: after a successful withdraw by a user, the contract's ether balance must have decreased by exactly the amount that user had in c.balances(sender) before the withdraw (call it preBalance). In P, it decreases by preBalance; in M, it does not decrease. So we test: if we record contract balance before and after withdraw, then (preContractBalance - postContractBalance) equals c.balances(sender) before withdraw.
        uint256 postContractBalance = address(c).balance;
        assertTrue(initialContractBalance - postContractBalance == initialSenderBalance);
    }
}
